import 'package:flutter/material.dart'; import '../models/user.dart'; import '../services/api.dart'; import '../widgets.dart'; import 'chat.dart';
class Communities extends StatefulWidget{final User user;const Communities({super.key,required this.user});@override State<Communities> createState()=>_CommunitiesState();}
class _CommunitiesState extends State<Communities>{final q=TextEditingController();List data=[];bool loading=false;@override void initState(){super.initState();load();}@override void dispose(){q.dispose();super.dispose();}Future<void> load()async{setState(()=>loading=true);try{final r=await Api.get('/communities?q=${Uri.encodeQueryComponent(q.text.trim())}');if(mounted)setState(()=>data=List.from(r['communities']??[]));}catch(x){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('$x'.replaceFirst('Exception: ',''))));}finally{if(mounted)setState(()=>loading=false);}}Future<void> create()async{final n=TextEditingController(),d=TextEditingController();final ok=await showDialog<bool>(context:context,builder:(c)=>AlertDialog(title:const Text('Create community'),content:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:n,decoration:const InputDecoration(labelText:'Community name')),TextField(controller:d,decoration:const InputDecoration(labelText:'Description'))]),actions:[TextButton(onPressed:()=>Navigator.pop(c),child:const Text('Cancel')),FilledButton(onPressed:()async{if(n.text.trim().isEmpty)return;await Api.post('/communities',{'name':n.text.trim(),'description':d.text.trim()});if(c.mounted)Navigator.pop(c,true);},child:const Text('Create'))]));n.dispose();d.dispose();if(ok==true)load();}Future<void> join(String id)async{try{final r=await Api.post('/communities/$id/join',{});if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(r['message']??'Request sent')));}catch(x){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('$x'.replaceFirst('Exception: ',''))));}}@override Widget build(BuildContext c)=>Column(children:[GradientHeader(title:'Find your people',subtitle:'Communities built by students',action:IconButton(onPressed:create,icon:const Icon(Icons.add_circle_outline))),Padding(padding:const EdgeInsets.all(16),child:TextField(controller:q,onChanged:(_)=>load(),decoration:InputDecoration(prefixIcon:const Icon(Icons.search),hintText:'Search communities',filled:true,suffixIcon:loading?const Padding(padding:EdgeInsets.all(12),child:CircularProgressIndicator()):null))),Expanded(child:data.isEmpty?const EmptyState(icon:Icons.groups_2_outlined,title:'No communities yet',text:'Create one and bring your people together.'):ListView.builder(padding:const EdgeInsets.symmetric(horizontal:16),itemCount:data.length,itemBuilder:(c,i){final x=Map<String,dynamic>.from(data[i]);final id='${x['_id']??''}',name='${x['name']??''}',desc='${x['description']??''}';return Padding(padding:const EdgeInsets.only(bottom:10),child:Card(child:ListTile(contentPadding:const EdgeInsets.all(14),leading:const CircleAvatar(child:Icon(Icons.groups)),title:Text(name,style:TextStyle(fontWeight:FontWeight.w800)),subtitle:Text(desc,maxLines:2,overflow:TextOverflow.ellipsis),trailing:OutlinedButton(onPressed:()=>join(id),child:const Text('Join')),onTap:()=>Navigator.push(c,MaterialPageRoute(builder:(_)=>Chat(user:widget.user,communityId:id,title:name)))));}))]);}
